nums = [2, 7, 11, 15]
target = 26

i, j = 0, len(nums) - 1
while i < j:
    s = nums[i] + nums[j]
    print(f'i={i} j={j} 和={s}')
    if s == target:
        print('命中:', i, j)
        break
    elif s < target:
        i += 1
    else:
        j -= 1

